// A class that can safely generate shared_ptrs to itself.
class EventHandler : public std::enable_shared_from_this<EventHandler> {
public:
    // Factory function to ensure objects are always managed by shared_ptr.
    static std::shared_ptr<EventHandler> create() {
        // Note: Using 'new' inside a helper is one way to access the private constructor.
        return std::shared_ptr<EventHandler>(new EventHandler());
    }

    // Member function that needs to pass a shared_ptr to this object.
    void registerWithEventManager() {
        // Safely get a shared_ptr to the current object.
        // This shares ownership with the eventManager.
        eventManager.registerHandler(shared_from_this());
    }

private:
    // Constructor is private to enforce creation via the factory.
    EventHandler() { /* ... */ }
};

// Correct Usage:
auto handler = EventHandler::create();
handler->registerWithEventManager(); // OK: an owning shared_ptr exists.

// Incorrect Usage:
// EventHandler badHandler; // Error: constructor is private.
// badHandler.registerWithEventManager(); // If it were possible, this would be undefined behavior.
